function localDemo(){try{const v=JSON.parse(localStorage.getItem(KEY)||'null');return v?validateData(v):seedDemo();}catch{return seedDemo();}}
const MODE_ORDER=['light','soft','dark'],MODE_ICON={"light": "<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4\"/></svg>", "soft": "<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 3a9 9 0 0 0 0 18z\" fill=\"currentColor\"/></svg>", "dark": "<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z\"/></svg>", "auto": "<svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"12\" rx=\"2\"/><path d=\"M8 20h8M12 16v4\"/></svg>"},MODE_NAME={light:'Sáng',soft:'Dịu',dark:'Tối',auto:'Tự động'};
const modeToggle=()=>{const next=MODE_ORDER[(MODE_ORDER.indexOf(prefs.mode)+1)%MODE_ORDER.length];return `<button type="button" class="top-settings mode-toggle" data-preference="mode" data-value="${next}" title="Chế độ hiển thị: ${MODE_NAME[prefs.mode]} (bấm để chuyển sang ${MODE_NAME[next]})" aria-label="Chế độ hiển thị: ${MODE_NAME[prefs.mode]}. Bấm để chuyển sang ${MODE_NAME[next]}">${MODE_ICON[prefs.mode]}</button>`;};
const fontSwitch=()=>`<div class="mode-switch font-switch" role="group" aria-label="Cỡ chữ">${[['small','Nhỏ',12],['medium','Vừa',16],['large','Lớn',21]].map(([v,n,px])=>`<button type="button" data-preference="font" data-value="${v}" aria-pressed="${prefs.font===v}"><span class="fs-a" style="font-size:${px}px" aria-hidden="true">A</span><span>${n}</span></button>`).join('')}</div>`;
const modeSwitch=()=>`<div class="mode-switch" role="group" aria-label="Chế độ sáng tối">${MODE_ORDER.map(m=>`<button type="button" data-preference="mode" data-value="${m}" aria-pressed="${prefs.mode===m}">${MODE_ICON[m]}<span>${MODE_NAME[m]}</span></button>`).join('')}</div>`;
const resolveMode=()=>['light','soft','dark'].includes(prefs.mode)?prefs.mode:'soft';
function applyPreferences(){const root=document.documentElement;if(!root)return;root.dataset.theme=prefs.theme;root.dataset.font=prefs.font;root.dataset.mode=resolveMode();root.dataset.modePref=prefs.mode;root.lang=prefs.lang;try{document.querySelector('meta[name="theme-color"]')?.setAttribute('content',resolveMode()==='dark'?'#0f0e22':'#6d3df0');}catch{}}
async function startCloud(){
 applyPreferences();
 if(runtime.preview){data=localDemo();runtime.mode='preview';return render();}
 if(!cloud.configured){runtime.mode='auth';runtime.error='';return render();}
 try{
  const recovery=new URLSearchParams(location.hash.slice(1));
  const inviteParam=new URLSearchParams(location.search).get('invite');if(inviteParam&&/^[A-Za-z0-9]{16,64}$/.test(inviteParam))try{sessionStorage.setItem('retailmind_invite',inviteParam);}catch{}
  if(recovery.get('error')||recovery.get('error_code')){const why=recovery.get('error_description')||recovery.get('error')||'';history.replaceState(null,'',location.pathname+location.search);runtime.mode='auth';runtime.tab='login';runtime.error=/expired|invalid/i.test(why)?'Liên kết xác nhận đã hết hạn hoặc đã dùng. Hãy đăng nhập hoặc yêu cầu gửi lại email.':'Không xác nhận được email: '+why.replace(/\+/g,' ');return render();}
  if(recovery.get('access_token')&&['signup','magiclink','invite','email_change'].includes(recovery.get('type'))){
   cloud.keepSession({access_token:recovery.get('access_token'),refresh_token:recovery.get('refresh_token'),expires_in:Number(recovery.get('expires_in')||3600)});
   cloud.user=await cloud.request('/auth/v1/user');history.replaceState(null,'',location.pathname+location.search);await showOrganizations();runtime.error='Đã xác nhận email thành công. Hãy tạo hoặc chọn doanh nghiệp để bắt đầu.';return render();
  }
  if(recovery.get('access_token')&&recovery.get('type')==='recovery'){
   cloud.keepSession({access_token:recovery.get('access_token'),refresh_token:recovery.get('refresh_token'),expires_in:Number(recovery.get('expires_in')||3600)});
   cloud.user=await cloud.request('/auth/v1/user');runtime.mode='reset';history.replaceState(null,'',location.pathname);return render();
  }
  if(await cloud.restore())return await showOrganizations();
  runtime.mode='auth';render();
 }catch(e){runtime.mode='auth';runtime.error=e.message;render();}
}
async function showOrganizations(){runtime.organizations=await cloud.organizations();runtime.mode='choose';runtime.error='';render();}
async function chooseOrganization(id){stopWake();window.speechSynthesis?.cancel();
 const org=runtime.organizations.find(o=>o.id===id);if(!org)throw Error('Không tìm thấy doanh nghiệp.');
 data=validateData(await cloud.loadOrganization(org));chatEpoch++;ui.chat=[{role:'assistant',text:'Xin chào! Mình có thể hỗ trợ phân tích dữ liệu và phương án của doanh nghiệp này.'}];ui.chatBusy=false;ui.chatInput='';ui.chatOpen=false;runtime.mode='app';runtime.blocked=false;runtime.error='';ui.page='dashboard';productImages.clear();await loadProductImages();render();
}
async function loadProductImages(){if(!cloud.org)return;await Promise.all((data.products||[]).filter(p=>p.imagePath).slice(0,100).map(async p=>{try{productImages.set(p.id,await cloud.fileUrl(p.imagePath));}catch{}}));}
function renderAccount(){const root=document.getElementById('app');root.innerHTML=runtime.mode==='choose'?organizationsView({user:cloud.user,organizations:runtime.organizations,error:runtime.error,loading:runtime.busy,inviteCode:(()=>{try{return sessionStorage.getItem('retailmind_invite')||''}catch{return ''}})()}):loginView({font:prefs.font,invited:(()=>{try{return Boolean(sessionStorage.getItem('retailmind_invite'))}catch{return false}})(),theme:prefs.theme,lang:prefs.lang,tab:runtime.tab,error:runtime.error,configured:cloud.configured,recovery:runtime.mode==='reset',theme:prefs.theme,lang:prefs.lang,mode:prefs.mode});translateUI(root,prefs.lang);}
async function authAction(form){
 if(runtime.busy)return;runtime.busy=true;runtime.error='';const x=Object.fromEntries(new FormData(form));
 try{
  if(form.id==='auth-entry'){
   if(x.mode==='signup'){if(x.password!==x.confirm)throw Error('Hai mật khẩu chưa trùng nhau.');await cloud.signup(x.email,x.password,location.origin+'/');runtime.tab='login';runtime.error='Đã gửi email xác minh. Hãy mở email và xác nhận trước khi đăng nhập.';}
   else if(x.mode==='forgot'){await cloud.recover(x.email,location.origin+'/');runtime.tab='login';runtime.error='Nếu email đã đăng ký, hệ thống sẽ gửi liên kết khôi phục.';}
   else if(x.mode==='reset'){await cloud.updatePassword(x.password);runtime.mode='auth';runtime.tab='login';await cloud.logout();runtime.error='Đã đặt lại mật khẩu. Hãy đăng nhập lại.';}
   else {await cloud.login(x.email,x.password);await showOrganizations();return;}
  }else if(form.id==='company-create'){
   const initial=baseState();initial.company.name=x.company.trim();
   const id=await cloud.createOrganization(x.company.trim(),initial);await showOrganizations();await chooseOrganization(id);return;
  }else if(form.id==='company-join'){
   const id=await cloud.joinOrganization(x.code.trim());try{sessionStorage.removeItem('retailmind_invite');}catch{}await showOrganizations();await chooseOrganization(id);return;
  }
 }catch(e){runtime.error=e.message||'Có lỗi xử lý tài khoản.';}
 finally{runtime.busy=false;render();}
}
