function setData(v,toast='Đã lưu thay đổi.') {
 if(runtime.mode!=='app' && runtime.mode!=='preview')throw Error('Cần chọn doanh nghiệp để ghi dữ liệu.');
 if(runtime.blocked)throw Error('Đã phát hiện thay đổi dữ liệu trên thiết bị khác; cần tải lại trang trước khi tiếp tục.');
 data=validateData(v);
 if(runtime.preview){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}render();notice('Đã lưu bản xem thử trên trình duyệt (không đồng bộ).');return;}
 const snapshot=structuredClone(data);runtime.saving++;render();notice(toast+' · Đang đồng bộ…');
 saveQueue=saveQueue.then(()=>cloud.saveState(snapshot)).then(()=>{runtime.saving--;updateSyncIndicator();}).catch(async error=>{
  runtime.saving=Math.max(0,runtime.saving-1);runtime.blocked=true;
  try{data=validateData(await cloud.loadOrganization(cloud.org));await loadProductImages();}catch{}
  render();notice('Không lưu được: '+(error.message||error)+'. Đã tải lại dữ liệu gần nhất; vui lòng kiểm tra trước khi thao tác tiếp.','bad');
 });
}
function updateSyncIndicator(){const e=document.getElementById('sync-status');if(e)e.textContent=runtime.saving?'● Đang đồng bộ':'● Đã đồng bộ';}

function notice(message,tone='ok'){const t=document.getElementById('toast');if(!t)return;t.className=`toast show ${tone}`;t.textContent=message;clearTimeout(notice.timer);notice.timer=setTimeout(()=>{t.className='toast';},4400);}
let lastMutationOk=true;function transactional(fn,msg){try{setData(fn(data),msg);lastMutationOk=true;return true;}catch(e){lastMutationOk=false;notice(e.message||'Dữ liệu không hợp lệ.','bad');return false;}}
function main(){
 const f=financials(data),r=simpleRecommendation(data),pr=procurementSummary(data),trend=monthlyRevenue(data,6),h=healthScore(data),cover=stockCover(data);
 const max=Math.max(1,...trend.map(x=>Math.max(x.revenue,x.expenses)));
 const overdue=(r.lateDeliveries||[]).length,low=r.low||[],debts=r.debts||[];
 const todo=[
  ...low.slice(0,2).map(p=>({icon:'inventory',tone:'orange',title:`${p.name} chạm ngưỡng tồn kho`,detail:`Hiện có ${integer(p.stock)} · Ngưỡng ${integer(p.min)}`,page:'inventory',tag:'Cần kiểm tra'})),
  ...(overdue?[{icon:'suppliers',tone:'rose',title:`${overdue} phiếu mua giao trễ`,detail:'Xem ngày hẹn và tiến độ nhận hàng',page:'suppliers',tag:'Ưu tiên'}]:[]),
  ...(f.missing.length?[{icon:'alert',tone:'purple',title:`${f.missing.length} đơn thiếu giá vốn`,detail:'Lợi nhuận chưa thể xác minh đầy đủ',page:'finance',tag:'Thiếu dữ liệu'}]:[]),
  ...(debts.length?[{icon:'finance',tone:'blue',title:`${debts.length} nhà cung cấp còn công nợ`,detail:'Kiểm tra thời hạn và lịch sử thanh toán',page:'suppliers',tag:'Theo dõi'}]:[])
 ];
 const totalActions=low.length+overdue+f.missing.length+debts.length;
 const top=salesByProduct(data).filter(x=>x.units>0).sort((a,b)=>b.units-a.units).slice(0,4);
 const pending=data.decisions.filter(x=>!/(Hoàn thành|Đã duyệt|Hủy)/.test(x.status||'')).length;
 const moneyOrNA=f.net===null?'Chưa đủ dữ liệu':money(f.net);
 const dateText=new Date().toLocaleDateString(prefs.lang==='en'?'en-US':'vi-VN',{weekday:'long',day:'numeric',month:'long'});
 const spark=(()=>{const v=trend.map(x=>x.revenue);const m=Math.max(1,...v);const pts=v.map((y,i)=>`${i*(100/(v.length-1||1))},${34-(y/m)*30}`).join(' ');return `<svg class="db-spark" viewBox="0 0 100 36" preserveAspectRatio="none" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;})();
 const kpis=[
  {k:'c1',icon:'forecast',label:'Doanh thu hoàn thành',value:money(f.revenue),detail:`${f.orders} đơn đã hoàn thành`,extra:spark},
  {k:'c2',icon:'orders',label:'Giá vốn đã xác minh',value:money(f.cogsKnown),detail:`${f.missing.length} đơn còn thiếu giá vốn`},
  {k:'c3',icon:'inventory',label:'Giá trị tồn kho',value:money(inventoryValue(data)),detail:`${data.products.length} mã sản phẩm`},
  {k:'c4',icon:'finance',label:'Lợi nhuận sau chi phí',value:moneyOrNA,detail:'Chưa bao gồm thuế và lãi vay'}
 ].map(z=>`<article class="db-kpi" style="--k:var(--${z.k})"><span class="db-kpi-ico">${ic(z.icon,20)}</span><small>${safe(z.label)}</small><strong>${z.value}</strong><em>${safe(z.detail)}</em>${z.extra||''}</article>`).join('');
 const weakest=h?[...h.parts].sort((a,b)=>a.score-b.score)[0]:null;
 const ring=h?`<div class="db-ring" style="--p:${h.score}"><b>${h.score}</b><small>/100</small></div>`:`<div class="db-ring empty"><b>—</b></div>`;
 const healthTile=`<section class="db-health tone-${h?h.tone:'warn'}">${ring}<div><small>ĐIỂM SỨC KHỎE KINH DOANH</small><h2>${h?safe(h.level):'Chưa đủ dữ liệu'}</h2><p>${h?`Chỉ số cần cải thiện nhất: <b>${safe(weakest.label)}</b> (${Math.round(weakest.score)}/100) — ${safe(weakest.detail)}.`:'Cần thêm đơn hoàn thành và sản phẩm để chấm điểm. Hệ thống không tự bịa số.'}</p><button type="button" data-go="analytics">Xem chi tiết chỉ số ${ic('arrow',14)}</button></div></section>`;
 const actionMarkup=todo.length?todo.slice(0,4).map((x,i)=>`<button type="button" class="db-todo tone-${x.tone}" data-go="${x.page}"><span class="db-todo-ico">${ic(x.icon,19)}</span><span class="db-todo-text"><b>${safe(x.title)}</b><small>${safe(x.detail)}</small></span><span class="db-todo-tag">${safe(x.tag)}</span></button>`).join(''):'<div class="db-calm"><span>✓</span><strong>Hoạt động ổn định</strong><small>Chưa có vấn đề nào vượt ngưỡng đang cấu hình.</small></div>';
 const chart=trend.map(x=>`<div class="db-col"><div class="db-col-bars"><i class="rev" style="height:${Math.max(2,x.revenue/max*100)}%" title="Doanh thu ${money(x.revenue)}"></i><i class="exp" style="height:${Math.max(2,x.expenses/max*100)}%" title="Chi phí ${money(x.expenses)}"></i></div><b>${safe(x.label)}</b><small>${x.revenue?integer(Math.round(x.revenue/1000))+'k':'0'}</small></div>`).join('');
 const topMarkup=top.length?top.map((x,i)=>{const p=data.products.find(p=>p.id===x.productId);return `<div class="db-top"><span class="db-rank">${i+1}</span><span class="db-top-img">${p?productPhoto(p):''}</span><span class="db-top-info"><b>${safe(x.name)}</b><small>Đã bán ${integer(x.units)} sản phẩm</small></span><strong>${money(x.revenue)}</strong></div>`}).join(''):empty('Chưa có dữ liệu bán theo sản phẩm hợp lệ.');
 const watch=cover.filter(x=>x.cover!==null||x.stock<=0).slice(0,4);
 const coverMarkup=watch.length?watch.map(x=>{const pct=x.cover===null?0:Math.max(4,Math.min(100,x.cover/60*100));const tone=x.status==='Sắp hết'||x.status==='Hết hàng'?'bad':x.status==='Tồn dư'?'warn':'ok';return `<div class="db-cover"><div><b>${safe(x.name)}</b><span class="status status-${tone}">${safe(x.status)}</span></div><div class="meter ${tone}"><i style="width:${pct}%"></i></div><small>${x.cover===null?'Chưa có lượng bán 30 ngày':`Đủ bán khoảng ${integer(x.cover)} ngày · tồn ${integer(x.stock)}`}</small></div>`}).join(''):empty('Chưa có lượng bán 30 ngày để ước tính số ngày tồn kho.');
 const prompts=[['Phân tích các vấn đề kinh doanh ưu tiên của doanh nghiệp từ dữ liệu hiện có, nêu căn cứ và 3 hành động phù hợp, không bịa số liệu.','Vấn đề ưu tiên'],['Các sản phẩm cần nhập kho ưu tiên và lý do dựa trên dữ liệu.','Nên nhập gì?'],['Gợi ý phương án cải thiện lợi nhuận dựa trên dữ liệu hiện có, nêu rủi ro.','Tăng lợi nhuận']];
 const quick=[['new-order','orders','Tạo đơn hàng'],['receive','suppliers','Tạo phiếu mua'],['new-product','products','Thêm sản phẩm'],['new-customer','customers','Thêm khách hàng'],['new-expense','finance','Ghi chi phí'],['new-decision','decisions','Tạo quyết định']];
 return `<section class="db-hero"><div class="db-hero-copy"><span class="db-date">${safe(dateText)}</span><h1>Xin chào, <em>${company()}</em></h1><p>${totalActions?`Hôm nay có <b>${totalActions} việc</b> cần ưu tiên và <b>${pending} quyết định</b> đang chờ theo dõi.`:'Mọi chỉ số đang ổn định. Hãy xem xu hướng để chuẩn bị bước tiếp theo.'}</p><div class="db-hero-cta"><button type="button" data-go="decisions" class="db-cta">Xem quyết định ${ic('arrow',16)}</button><button type="button" data-go="analytics" class="db-cta ghost">Khám phá số liệu</button></div></div>${healthTile}<i class="db-blob b1"></i><i class="db-blob b2"></i><i class="db-blob b3"></i></section>
 <div class="db-kpis">${kpis}</div>
 <section class="db-grid">
  <div class="db-card db-todos"><header><span class="db-chip">${ic('decisions',18)}</span><div><h2>Bản đồ quyết định hôm nay</h2><p>Việc ưu tiên từ dữ liệu thực tế</p></div><span class="db-count">${totalActions} vấn đề</span></header><div class="db-todo-list">${actionMarkup}</div></div>
  <div class="db-card db-chart"><header><span class="db-chip">${ic('analytics',18)}</span><div><h2>Doanh thu &amp; chi phí 6 tháng</h2><p>Chỉ tính đơn hoàn thành và chi phí vận hành đã ghi</p></div><button type="button" class="db-link" data-go="finance">Tài chính ${ic('arrow',13)}</button></header><div class="db-legend"><span class="rev">Doanh thu</span><span class="exp">Chi phí vận hành</span></div><div class="db-cols">${chart}</div></div>
  <div class="db-card db-tops"><header><span class="db-chip">${ic('products',18)}</span><div><h2>Sản phẩm nổi bật</h2><p>Xếp theo số lượng thực bán</p></div><button type="button" class="db-link" data-go="products">Tất cả ${ic('arrow',13)}</button></header>${topMarkup}</div>
  <div class="db-card db-covers"><header><span class="db-chip">${ic('inventory',18)}</span><div><h2>Tồn kho còn bán được bao lâu</h2><p>Theo tốc độ bán 30 ngày gần nhất</p></div><button type="button" class="db-link" data-go="analytics">Phân tích ${ic('arrow',13)}</button></header>${coverMarkup}</div>
  <div class="db-card db-ai"><header><span class="db-chip">${ic('spark',18)}</span><div><h2>Trợ lý phân tích AI</h2><p>Gemini giải thích · mô hình DSS tính số</p></div></header><p>Hãy hỏi về xu hướng, nguyên nhân và so sánh phương án. Kết quả mô hình DSS và phản hồi AI luôn được tách riêng.</p><div class="db-prompts">${prompts.map(([q,l])=>`<button type="button" data-chat-prompt="${safe(q)}">${ic('spark',13)}${safe(l)}</button>`).join('')}</div></div>
 </section>
 <section class="db-quick"><strong>Thao tác nhanh</strong>${quick.map(([a,i,l])=>`<button type="button" data-action="${a}">${ic(i,17)}${l}</button>`).join('')}<button type="button" data-action="palette" class="alt">${ic('search',17)}Tìm nhanh <kbd>Ctrl K</kbd></button></section>`;
}

function pageOrders(){const rows=data.orders.filter(o=>search(o.id+' '+o.customerName+' '+o.status));return `${head('Bán hàng & thanh toán','Lập đơn, theo dõi giao dịch và lưu chứng từ thanh toán của khách.',btn('＋ Tạo đơn hàng','new-order','primary'))}<div class="metrics three">${card('Phải thu từ khách',money(customerReceivables(data)),'Đơn hoàn thành chưa thu đủ','◉','orange')}${card('Đơn hàng',integer(data.orders.length),'Toàn bộ trạng thái','▤')}${card('Đã thu từ khách',money(procurementSummary(data).cashReceived),'Theo lịch sử nhận và hoàn tiền','↗','green')}</div>${panel('Danh sách đơn hàng',table(['Mã / ngày','Khách hàng / nơi giao','Sản phẩm','Tổng đơn','Đã thu · Còn thu','Trạng thái','Thao tác'],rows.map(o=>tableRow([`<span class="code">${safe(o.id)}</span><small>${date(o.date)}</small>`,safe(o.customerName||customerName(o.customerId))+`<small>${safe(o.deliveryAddress||'Chưa ghi địa chỉ giao')}</small>`,o.lines?.length?o.lines.map(l=>`${safe(l.name||productName(l.productId))} × ${integer(l.quantity)}`).join('<br>'):'<span class="subtle">Đơn cũ thiếu dòng SKU</span>',`<strong>${money(o.total)}</strong>`,`<strong>${money(orderPaid(o))}</strong><small>${o.total>orderPaid(o)?'Còn phải thu: '+money(Math.max(0,o.total-orderPaid(o))):'Đã thu đủ'}</small>`,badge(o.status),`${o.status==='Đã hủy'?'<div class="cancelled-order-label">Đã hủy · Chỉ xem lịch sử</div>':`<select aria-label="Trạng thái đơn hàng" data-order-status="${safe(o.id)}"><option ${o.status==='Đang xử lý'?'selected':''}>Đang xử lý</option><option ${o.status==='Hoàn thành'?'selected':''}>Hoàn thành</option><option>Đã hủy</option></select>`}<div class="row-actions">${btn('Chi tiết & ảnh','order-detail','compact',`data-id="${safe(o.id)}"`)}${o.status!=='Đã hủy'&&orderPaid(o)<o.total?btn('Thu tiền','pay-order','compact',`data-id="${safe(o.id)}"`):''}${orderPaid(o)>0?btn('Hoàn tiền','refund-order','compact',`data-id="${safe(o.id)}"`):''}${btn('Thêm chứng từ','attach-evidence','compact',`data-id="orderproof:${safe(o.id)}"`)}${btn('Xem ảnh','view-evidence','compact',`data-id="orderproof:${safe(o.id)}"`)}</div>`]))))}${panel('Lịch sử nhận tiền & hoàn tiền',table(['Ngày','Đơn hàng','Loại','Số tiền','Phương thức / tham chiếu','Chứng từ'],data.orders.flatMap(o=>[...(o.payments||[]).map(pay=>tableRow([date(pay.date),safe(o.id),'Khách thanh toán',money(pay.amount),safe([pay.method,pay.reference].filter(Boolean).join(' · ')),btn('Xem chứng từ','view-evidence','compact',`data-id="orderpay:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="orderpay:${safe(pay.id)}"`)])),...(o.refunds||[]).map(pay=>tableRow([date(pay.date),safe(o.id),'Hoàn tiền khách',money(pay.amount),safe([pay.method,pay.reference].filter(Boolean).join(' · ')),btn('Xem chứng từ','view-evidence','compact',`data-id="refund:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="refund:${safe(pay.id)}"`)]))])))}<p class="caption">Trạng thái Hoàn thành chỉ ghi nhận việc bán hàng; tiền khách thực trả được ghi riêng. Đơn đã thu tiền phải hoàn đủ trước khi hủy.</p>`;}
function productIllustration(p){const cat=String(p.category||'').toLowerCase(),nm=String(p.name||'').toLowerCase(),t=cat+' '+nm;
 const key=/thời trang|quần|áo|giày|túi|mũ/.test(t)?'fashion':/điện tử|công nghệ|tai nghe|bàn phím|đèn led|máy tính/.test(t)?'electronics':/gia dụng|nhà cửa|đồ dùng/.test(t)?'household':/mỹ phẩm|chăm sóc da/.test(t)?'beauty':/đồ uống|nước|cà phê/.test(t)?'beverage':/thực phẩm|mì|bánh|ăn vặt/.test(t)?'food':/sách|văn phòng|giấy|bút|sổ/.test(t)?'office':'other';
 return '/assets/'+key+'.svg';}
function productPhoto(p){const url=productImages.get(p.id)||p.imageData||productIllustration(p);return `<img loading="lazy" src="${safe(url)}" alt="${safe(p.name)}" class="product-thumb" onerror="this.onerror=null;this.src='/assets/other.svg'">`;}
function pageProducts(){const list=data.products.filter(p=>search(p.name+' '+p.sku+' '+p.category));const view=ui.productView;
 const toggle=`<div class="seg" role="group" aria-label="Kiểu hiển thị"><button type="button" class="${view==='grid'?'on':''}" data-action="products-view" data-id="grid" aria-pressed="${view==='grid'}">Thẻ</button><button type="button" class="${view==='table'?'on':''}" data-action="products-view" data-id="table" aria-pressed="${view==='table'}">Bảng</button></div>`;
 const grid=list.length?`<div class="pgrid">${list.map(p=>{const pct=Math.max(4,Math.min(100,p.stock/Math.max(1,p.min*3)*100));const low=p.stock<=p.min;return `<article class="pcard" style="--k:var(--c${hueOf(p.category)})"><div class="pcard-media">${productPhoto(p)}<span class="pcard-cat">${safe(p.category||'Khác')}</span>${low?'<span class="pcard-flag">Thiếu hàng</span>':''}${p.active===false?'<span class="pcard-flag off">Ngừng bán</span>':''}</div><div class="pcard-body"><span class="code">${safe(p.sku)}</span><h3>${safe(p.name)}</h3><div class="pcard-price"><strong>${money(p.price)}</strong><small>${p.cost?'Vốn '+money(p.cost):'Chưa nhập kho'}</small></div><div class="meter ${low?'bad':'ok'}" role="img" aria-label="Tồn ${p.stock}, ngưỡng ${p.min}"><i style="width:${pct}%"></i></div><div class="pcard-meta"><span>Tồn <b>${integer(p.stock)}</b> / ngưỡng ${integer(p.min)}</span><span>${safe(supplierName(p.supplierId))}</span></div><div class="pcard-actions">${btn('Sửa','edit-product','compact',`data-id="${safe(p.id)}"`)}<button type="button" class="btn compact" data-go="inventory">Xem kho</button></div></div></article>`}).join('')}</div>`:empty('Chưa có sản phẩm phù hợp.');
 const tableView=panel('Sản phẩm đang quản lý',table(['Mã SKU','Sản phẩm','Danh mục','Giá bán','Giá vốn bình quân','Nhà cung cấp','Tồn hiện tại','Thao tác'],list.map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,`<span class="product-name-cell">${productPhoto(p)}<span><strong>${safe(p.name)}</strong><small>${p.active===false?'Ngừng bán':'Đang bán'}</small></span></span>`,safe(p.category),money(p.price),p.cost?money(p.cost):'<span class="muted">Chưa nhập kho</span>',safe(supplierName(p.supplierId)),integer(p.stock),btn('Sửa','edit-product','compact',`data-id="${safe(p.id)}"`)]))));
 return `${head('Danh mục sản phẩm','Quản lý mã hàng, danh mục, giá bán và giá vốn tự động.',`${toggle}${btn('＋ Thêm sản phẩm','new-product','primary')}`)}${view==='grid'?grid:tableView}<p class="caption">Giá vốn bình quân được tính từ hàng đã nhận; giá vốn trên đơn đã bán được giữ tại thời điểm giao dịch.</p>`;}
function pageInventory(){const low=data.products.filter(p=>p.stock<=p.min&&p.active!==false);return `${head('Tồn kho & kiểm kê','Luồng riêng biệt: nhận hàng từ nhà cung cấp, ghi công nợ, điều chỉnh tồn và xem nhật ký.',`${btn('＋ Tạo phiếu nhập tại Nhà cung cấp','go-purchase','primary')} ${btn('Kiểm kê','audit')}`)}<div class="metrics three">${card('Sản phẩm đang theo dõi',integer(data.products.length),'SKU trong danh mục','▦')}${card('Giá trị tồn kho',money(inventoryValue(data)),'Giá vốn × tồn hiện tại','◈','green')}${card('Cảnh báo thiếu hàng',integer(low.length),'Tồn không lớn hơn ngưỡng','⚑','orange')}</div>${panel('Tồn kho theo SKU',table(['SKU','Sản phẩm','Tồn','Ngưỡng','Trạng thái','Vốn cần bổ sung tới ngưỡng'],data.products.filter(p=>search(p.name+' '+p.sku)).map(p=>tableRow([`<span class="code">${safe(p.sku)}</span>`,safe(p.name),`<b>${integer(p.stock)}</b><div class="meter ${p.stock<=p.min?'bad':'ok'}"><i style="width:${Math.max(4,Math.min(100,p.stock/Math.max(1,p.min*3)*100))}%"></i></div>`,integer(p.min),badge(p.stock<=p.min?'Thiếu hàng':'Đủ hàng'),money(Math.max(0,p.min-p.stock)*p.cost)]))))}${panel('Nhật ký nhập / xuất / kiểm kê',table(['Ngày','Nghiệp vụ','Tham chiếu','Biến động','Lý do','Biên bản'],data.stockLedger.slice(0,40).map(x=>tableRow([date(x.date),badge(x.type),`<span class="code">${safe(x.ref)}</span>`,(x.lines||[]).map(l=>`${safe(productName(l.productId))}: ${l.quantity>0?'+':''}${integer(l.quantity)}`).join('<br>'),safe(x.reason||'—'),x.type==='Kiểm kê'?btn('Xem ảnh/PDF','view-evidence','compact',`data-id="audit:${safe(x.id)}"`):'—']))))}`;}
function pageSuppliers(){
 const ps=procurementSummary(data);
 const supplierRows=data.suppliers.filter(s=>search(s.name)).map(s=>{
  const st=supplierDeliveryStats(data,s.id);
  return tableRow([`<strong>${safe(s.name)}</strong><small>${safe(s.id)}</small>`,`${safe(s.type||'Hàng hóa')}<small>${safe(s.phone||s.contact||'—')}</small>`,safe(supplierPolicies(s)),`${integer(s.deliveryDays||0)} ngày`,st.sample?`${st.onTime}/${st.sample} lần (${st.onTimePct}%)`:'<span class="muted">Chưa có dữ liệu</span>',money(supplierDebt(data,s.id)),btn('Sửa','edit-supplier','compact',`data-id="${safe(s.id)}"`)]);
 });
 const purchaseRows=data.purchases.map(p=>tableRow([
  `<span class="code">${safe(p.id)}</span><small>${date(p.date)}</small>`,safe(supplierName(p.supplierId)),safe(productName(p.productId)),`${integer(p.orderedQuantity??p.quantity)} / ${integer(p.quantity||0)}`,`<small>${date(p.expectedDelivery)} / ${date(p.deliveredDate)}</small>`,money(!delivered(p)?p.plannedValue:(p.landedTotal??p.total)),money(Math.max(0,p.total-p.paid)),
  `${badge(p.deliveryStatus||'Đã nhận')}<div class="row-actions">${p.deliveryStatus==='Chờ giao'?btn('Đang giao','mark-transit','compact',`data-id="${safe(p.id)}"`):''}${!delivered(p)?btn('Xác nhận đã nhận','confirm-receipt','compact',`data-id="${safe(p.id)}"`):''}${btn('Hóa đơn','view-evidence','compact',`data-id="purchase:${safe(p.id)}"`)}${delivered(p)?btn('Phiếu giao','view-evidence','compact',`data-id="receipt:${safe(p.id)}"`):''}</div>`
 ]));
 const chargeRows=data.purchases.flatMap(p=>(p.charges||[]).map(c=>tableRow([safe(p.id),safe(supplierName(c.partnerId)),safe(c.kind),money(c.amount),money(c.paid),money(c.amount-c.paid),c.amount>c.paid?btn('Thanh toán','pay-service','compact',`data-id="${safe(p.id)}|${safe(c.id)}"`):'Đã trả'])));
 const paymentRows=data.purchases.flatMap(p=>[
  ...(p.payments||[]).map(pay=>tableRow([date(pay.date),safe(p.id),safe(supplierName(p.supplierId)),money(pay.amount),safe(pay.reference||'—'),btn('Xem chứng từ','view-evidence','compact',`data-id="payment:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="payment:${safe(pay.id)}"`)])),
  ...(p.charges||[]).flatMap(c=>(c.payments||[]).map(pay=>tableRow([date(pay.date),safe(p.id),safe(supplierName(c.partnerId)),money(pay.amount),safe(pay.reference||'—'),btn('Xem chứng từ','view-evidence','compact',`data-id="payment:${safe(pay.id)}"`)+' '+btn('Bổ sung ảnh/PDF','attach-evidence','compact',`data-id="payment:${safe(pay.id)}"`)])))
 ]);
 return `${head('Nhà cung cấp & mua hàng','Theo dõi giao hàng, đặt mua, nhận hàng, công nợ và chứng từ.',`${btn('＋ Thêm đối tác','new-supplier','primary')} ${btn('＋ Tạo phiếu mua','receive','primary')} ${btn('Trả nhà cung cấp','pay')} ${btn('Trả phí dịch vụ','pay-service')} ${btn('Đánh giá nhà cung cấp','go-ranking')}`)}
 <div class="metrics three">${card('Đối tác',integer(data.suppliers.length),'Nhà cung cấp và dịch vụ','♧')}${card('Còn phải trả',money(ps.debtOutstanding+ps.serviceDebt),'Gồm cả phí vận chuyển','◉','orange')}${card('Phiếu mua chờ giao',integer(data.purchases.filter(x=>!delivered(x)).length),'Chưa cộng vào tồn kho','▥')}</div>
 ${panel('Thông tin đối tác',table(['Đối tác','Loại / liên hệ','Chính sách giao','Dự kiến','Đúng hẹn','Công nợ hàng hóa','Sửa'],supplierRows))}
 ${panel('Chứng từ mua hàng · Đơn mua và giao nhận',table(['Mã phiếu','Nhà cung cấp','Sản phẩm','Đặt / nhận','Hẹn / đã giao','Giá trị','Nợ NCC','Trạng thái · Chứng từ'],purchaseRows))}
 ${panel('Công nợ vận chuyển và bốc xếp',table(['Phiếu','Đối tác','Loại phí','Phải trả','Đã trả','Còn nợ','Thao tác'],chargeRows))}
 ${panel('Lịch sử thanh toán & chứng từ',table(['Ngày','Phiếu','Người nhận','Số tiền','Tham chiếu','Chứng từ'],paymentRows))}
 <p class="caption">Chỉ xác nhận nhận hàng khi đã kiểm đếm thực tế. Một lần trả nợ tương ứng một chứng từ riêng.</p>`;
}
function pageCustomers(){const list=data.customers.filter(c=>search(c.name+' '+c.phone));
 const cards=list.length?`<div class="cgrid">${list.map(c=>{const od=data.orders.filter(o=>o.customerId===c.id),done=od.filter(o=>o.status==='Hoàn thành'),rev=done.reduce((z,o)=>z+Number(o.total),0),owe=done.reduce((z,o)=>z+Math.max(0,o.total-orderPaid(o)),0);return `<article class="ccard" style="--k:var(--c${hueOf(c.name)})"><div class="ccard-top"><span class="avatar">${safe(initials(c.name))}</span><div><h3>${safe(c.name)}</h3><small>${safe(c.id)}</small></div>${owe>0?'<span class="status status-warn">Còn nợ</span>':od.length?'<span class="status status-ok">Tốt</span>':''}</div><p class="ccard-contact">${safe(c.phone||c.email||'Chưa có liên hệ')}<br><span>${safe(c.address||'Chưa có địa chỉ mặc định')}</span></p><dl><div><dt>Tổng đơn</dt><dd>${integer(od.length)}</dd></div><div><dt>Doanh thu</dt><dd>${money(rev)}</dd></div><div><dt>Còn phải thu</dt><dd class="${owe>0?'negative':''}">${money(owe)}</dd></div></dl><div class="ccard-actions">${btn('Sửa','edit-customer','compact',`data-id="${safe(c.id)}"`)}</div></article>`}).join('')}</div>`:empty('Chưa có khách hàng phù hợp.');
 return `${head('Khách hàng','Lưu thông tin giao hàng và xem lịch sử mua, công nợ từ đơn hàng.',btn('＋ Thêm khách hàng','new-customer','primary'))}${cards}`;}
function monthOptions(){const set=new Set([new Date().toISOString().slice(0,7),...data.expenses.map(e=>String(e.date).slice(0,7)),...data.orders.map(o=>String(o.date).slice(0,7)),...data.purchases.map(p=>String(p.date).slice(0,7)),...data.purchases.flatMap(p=>(p.payments||[]).map(x=>String(x.date).slice(0,7)))].filter(x=>/^\d{4}-\d\d$/.test(x)));return `<select aria-label="Chọn kỳ tài chính" data-filter-month><option value="all" ${ui.month==='all'?'selected':''}>Toàn bộ dữ liệu</option>${[...set].sort().reverse().map(m=>`<option value="${m}" ${ui.month===m?'selected':''}>Tháng ${m.slice(5)}/${m.slice(0,4)}</option>`).join('')}</select>`;}
function pageFinance(){const f=financials(data,ui.month),p=procurementSummary(data,ui.month);return `${head('Tài chính & báo cáo','Lợi nhuận và dòng tiền nhập hàng được theo dõi riêng, không trừ hai lần tiền mua hàng.',`${monthOptions()} ${btn('＋ Ghi chi phí','new-expense','primary')} ${btn('✦ AI phân tích tài chính','finance-ai','primary')} ${btn('Xuất báo cáo CSV','export-report')}`)}<div class="metrics">${card('Doanh thu',money(f.revenue),`${f.orders} đơn hoàn thành`,'↗','green')}${card('Giá vốn xác minh',money(f.cogsKnown),`${f.missing.length} đơn thiếu giá vốn`,'▤')}${card('Chi phí vận hành',money(f.expenses),'Không bao gồm nhập kho','↘','orange')}${card('Lợi nhuận sau chi phí',f.net===null?'Không đủ dữ liệu':money(f.net),f.missing.length?'Chưa thể xác nhận tổng lợi nhuận':'Trước thuế / lãi vay','◉',f.net===null?'orange':'green')}</div>${panel('Dòng tiền khách hàng',`<div class="procurement-summary"><div><small>Thực thu từ khách trong kỳ</small><strong>${money(p.cashReceived)}</strong></div><div><small>Phải thu khách hiện tại</small><strong>${money(customerReceivables(data))}</strong></div><div><small>Còn phải trả dịch vụ</small><strong>${money(p.serviceDebt)}</strong></div></div><p class="caption">Doanh thu ghi theo đơn hoàn thành; thu tiền theo chứng từ đã ghi nhận. Hai chỉ tiêu không bắt buộc bằng nhau.</p>`)}${panel('Tiền mua hàng & công nợ (không trừ trực tiếp vào lợi nhuận)',`<div class="procurement-summary"><div><small>Tiền hàng nhập trong kỳ</small><strong>${money(p.purchaseValue)}</strong></div><div><small>Phí nhập kho đã phân bổ</small><strong>${money(p.landed-p.purchaseValue)}</strong></div><div><small>Đã trả nhà cung cấp trong kỳ</small><strong>${money(p.paidSupplier)}</strong></div><div><small>Phí bên ngoài đã trả khi nhập</small><strong>${money(p.paidExternal)}</strong></div><div><small>Tổng chi tiền nhập hàng trong kỳ</small><strong>${money(p.paidSupplier+p.paidExternal)}</strong></div><div class="outflow-total"><small>TỔNG TIỀN ĐÃ CHI (mua hàng và vận hành)</small><strong>${money(p.paidSupplier+p.paidExternal+f.expenses)}</strong></div><div><small>Công nợ NCC hiện tại</small><strong>${money(p.debtOutstanding)}</strong></div><div><small>Công nợ dịch vụ hiện tại</small><strong>${money(p.serviceDebt)}</strong></div></div><p class="caption">Tiền nhập hàng tự động tăng dòng tiền chi khi thanh toán, nhưng không làm giảm ngay lợi nhuận. Giá trị hàng tồn sẽ đi vào giá vốn khi bán. Phí vận chuyển về kho được phân bổ vào giá vốn, không nhập lại vào chi phí hoạt động. ${btn('Xem phiếu nhập & thanh toán','go-purchase','compact')}</p>`)}${f.missing.length?`<div class="notice-warn"><strong>Thiếu cơ sở tính lợi nhuận:</strong> ${f.missing.length} đơn hoàn thành không có đầy đủ dòng hàng / giá vốn. Doanh thu vẫn được ghi nhận, nhưng không thể tính tổng lợi nhuận chính xác. <small>Đơn: ${f.missing.slice(0,6).map(safe).join(', ')}</small></div>`:''}<div class="columns half">${panel('Công thức tài chính',`<div class="formula"><div><span>Doanh thu hoàn thành</span><strong>${money(f.revenue)}</strong></div><div><span>Giá vốn đã biết</span><strong>− ${money(f.cogsKnown)}</strong></div><div><span>Chi phí hoạt động</span><strong>− ${money(f.expenses)}</strong></div><div class="formula-result"><span>Kết quả kinh doanh</span><strong>${f.net===null?'Chưa xác định':money(f.net)}</strong></div></div><p class="caption">Không bao gồm thuế, chi phí lãi vay và hàng trả lại ngoài quy trình đổi trạng thái.</p>`)}${panel('Cơ cấu chi phí',(()=>{const m={};for(const x of f.expenseRows)m[x.category]=(m[x.category]||0)+x.amount;const max=Math.max(...Object.values(m),1);return Object.entries(m).length?Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([cat,value])=>`<div class="expense-bar"><span>${safe(cat)}</span><strong>${money(value)}</strong><div><i style="width:${value/max*100}%"></i></div></div>`).join(''):empty();})())}</div>${panel('Các khoản chi đã ghi nhận',table(['Ngày','Tên khoản chi','Nhóm chi phí','Số tiền','Thao tác'],f.expenseRows.filter(e=>search(e.name+' '+e.category)).map(e=>tableRow([date(e.date),safe(e.name),safe(e.category),money(e.amount),`${btn('Sửa','edit-expense','compact',`data-id="${safe(e.id)}"`)} ${btn('Chứng từ','view-evidence','compact',`data-id="expense:${safe(e.id)}"`)} ${btn('Xóa','delete-expense','compact danger',`data-id="${safe(e.id)}"`)}`]))))}`;}
function healthPanel(){const h=healthScore(data);if(!h)return `<section class="health-card"><div class="health-ring muted-ring"><b>—</b></div><div class="health-body"><h2>Điểm sức khỏe kinh doanh</h2><p>Cần thêm đơn hàng hoàn thành và sản phẩm để chấm điểm. Hệ thống không tự bịa số liệu.</p></div></section>`;
 return `<section class="health-card tone-${h.tone}"><div class="health-ring" style="--p:${h.score}"><b>${h.score}</b><small>/100</small></div><div class="health-body"><h2>Điểm sức khỏe kinh doanh · <em>${safe(h.level)}</em></h2><p>Tổng hợp ${h.parts.length} chỉ số đo được từ dữ liệu thực (độ phủ trọng số ${h.coverage}%).</p><div class="health-parts">${h.parts.map(x=>`<div class="health-part"><span>${safe(x.label)}</span><div class="health-bar"><i style="width:${Math.round(x.score)}%;background:${x.score>=75?'#10a67a':x.score>=50?'#e59a1b':'#e0455b'}"></i></div><small>${Math.round(x.score)}/100 · ${safe(x.detail)}</small></div>`).join('')}</div></div></section>`;}
function insightPanels(){const abc=abcAnalysis(data),cover=stockCover(data);
 const abcPanel=panel('Phân loại ABC theo doanh thu (Pareto)',abc.length?table(['Nhóm','Sản phẩm','Doanh thu','Tỷ trọng','Lũy kế'],abc.map(x=>tableRow([`<span class="abc abc-${x.klass}">${x.klass}</span>`,safe(x.name),money(x.revenue),(x.share*100).toFixed(1)+'%',(x.cumulative*100).toFixed(1)+'%'])))+'<p class="caption">A: nhóm tạo 80% doanh thu đầu tiên — ưu tiên đảm bảo tồn kho. B: 15% tiếp theo. C: phần còn lại — cân nhắc giảm nhập hoặc thanh lý.</p>':empty('Chưa có đơn hoàn thành với dòng sản phẩm hợp lệ.'));
 const coverPanel=panel('Số ngày tồn kho còn đáp ứng (30 ngày bán gần nhất)',table(['Sản phẩm','Tồn','Đã bán 30 ngày','Đủ bán trong','Đánh giá'],cover.map(x=>tableRow([safe(x.name),integer(x.stock),integer(x.units),x.cover===null?'—':integer(x.cover)+' ngày',`<span class="status status-${x.status==='Hợp lý'?'ok':x.status==='Sắp hết'||x.status==='Hết hàng'?'bad':'warn'}">${safe(x.status)}</span>`])))+'<p class="caption">Số ngày = tồn hiện tại ÷ tốc độ bán bình quân/ngày. Dưới 7 ngày: sắp hết; trên 90 ngày: tồn dư. Chỉ là chỉ báo tham khảo khi lịch sử bán còn ít.</p>');
 return `<div class="columns half">${abcPanel}${coverPanel}</div>`;}
function pageAnalytics(){const sales=salesByProduct(data).filter(z=>z.units>0);const trend=monthlyRevenue(data,6);const categories={};for(const x of sales){const p=data.products.find(p=>p.id===x.productId);const key=p?.category||'Khác';categories[key]=(categories[key]||0)+x.revenue;}const total=Object.values(categories).reduce((z,x)=>z+x,0);return `${head('Phân tích kinh doanh','Dữ liệu đã ghi nhận — không dùng ước lượng doanh thu theo SKU cho đơn lịch sử thiếu dòng hàng.')}${panel('Xu hướng 6 tháng',table(['Tháng','Doanh thu','Chi phí hoạt động','Tỷ lệ chi phí / doanh thu'],trend.map(x=>tableRow([x.month,money(x.revenue),money(x.expenses),x.revenue?(x.expenses/x.revenue*100).toFixed(1)+'%':'—']))))}<div class="columns half">${panel('Hiệu quả theo sản phẩm',table(['Sản phẩm','Số lượng bán','Doanh thu'],sales.map(x=>tableRow([safe(x.name),integer(x.units),money(x.revenue)]))))}${panel('Đóng góp doanh thu theo danh mục',total?Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="expense-bar"><span>${safe(name)}</span><strong>${(100*value/total).toFixed(1)}%</strong><div><i style="width:${value/total*100}%"></i></div></div>`).join(''):empty('Chưa có đơn hoàn thành với dòng sản phẩm hợp lệ.'))}</div>${insightPanels()}`;}
function pageForecast(){
 if(!ui.forecastProduct&&data.products.length)ui.forecastProduct=data.products[0].id;
 const p=data.products.find(p=>p.id===ui.forecastProduct);
 const v=p?analyzeDemand(data,p.id,p.stock||0,p.min||0):null;
 return `${head('Dự báo nhu cầu','Phân tích xu hướng từ lịch sử bán hàng; AI giải thích kịch bản, không tự tạo số dự báo.')}
 ${panel('Chọn mặt hàng',`<div class="row-control"><label>SKU cần dự báo</label><select data-forecast-product>${data.products.map(x=>`<option value="${safe(x.id)}" ${ui.forecastProduct===x.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select></div>`)}
 ${v&&v.sampleOrders>=3?`<div class="metrics three">${card('Đã bán 30 ngày gần nhất',integer(v.last30)+' sp',`${v.sampleOrders} đơn có sản phẩm đang xét`,'▤','blue')}${card('Nhu cầu 30 ngày tham khảo',v.sufficient?integer(v.projected)+' sp':'Chưa đủ dữ liệu',v.sufficient?'Bình quân có trọng số theo 3 giai đoạn':'Chưa đủ lịch sử để xác định xu hướng','⌁','purple')}${card('Lượng nhập cần cân nhắc',v.sufficient?integer(v.reorder)+' sp':'—',v.sufficient?'Tính từ tồn kho và ngưỡng an toàn':'Không đề xuất số khi dữ liệu thiếu','▣','orange')}</div>
 ${panel('Xu hướng bán hàng và mức tin cậy',`<div class="forecast-trend">${v.windows.map((x,i)=>`<div class="forecast-period"><span>${['60–90 ngày trước','30–60 ngày trước','30 ngày gần nhất'][i]}</span><div><i style="width:${Math.max(3,x/Math.max(1,...v.windows)*100)}%"></i></div><strong>${integer(x)} sp</strong></div>`).join('')}</div><p><strong>Xu hướng:</strong> ${safe(v.trendLabel)} · <strong>Độ tin cậy:</strong> ${safe(v.confidence)}</p><p class="caption">${safe(String(v.explanation).replace(/\.+$/,''))}. Dữ liệu đơn hàng không đủ liên tục hoặc có biến động sẽ làm kết quả kém tin cậy. Đây không phải số liệu do Gemini tự dự đoán.</p>${v.sufficient?btn('Lưu phương án dự báo thành quyết định','forecast-to-decision','primary',`data-id="${safe(p.id)}"`):''}`)}
 ${panel('Giải thích và so sánh bằng AI',`<p>Gemini có thể giải thích nguyên nhân tăng/giảm và đề xuất kịch bản nhập hàng. Kết luận phải dựa trên số liệu và ghi rõ những giả định.</p><button type="button" class="btn primary" data-chat-prompt="Phân tích nhu cầu sản phẩm ${safe(p.name)} theo lịch sử bán hàng của doanh nghiệp. So sánh các kịch bản nhu cầu tăng hoặc giảm, giải thích độ tin cậy và lượng nhập phù hợp; tuyệt đối không bịa dữ liệu.">✧ Yêu cầu Gemini phân tích dự báo</button>`)}
 `:`${panel('Dữ liệu chưa đủ để dự báo đáng tin cậy',`<div class="notice-warn">${v?safe(v.explanation):'Chưa có mặt hàng để phân tích.'} Hệ thống không dùng số bán kỳ trước làm dự báo chắc chắn.</div><p class="caption">Hãy tích lũy lịch sử giao dịch qua nhiều kỳ; ưu tiên thêm các đơn có ngày bán và SKU đầy đủ.</p>`)}`}`;
}

function sensitivityPanel(){
 const base=scenario(data,{pricePct:0,unitsPct:0,costPct:0,expensesPct:0},ui.month);
 if(!base)return panel('Kiểm tra độ nhạy',empty('Chưa có đủ giá vốn xác minh để phân tích độ nhạy.'));
 const risks=[['Giá bán giảm 10%',{pricePct:-10}],['Lượng bán giảm 20%',{unitsPct:-20}],['Giá vốn tăng 10%',{costPct:10}],['Chi phí hoạt động tăng 15%',{expensesPct:15}]];
 const rows=risks.map(([title,change])=>{
   const r=scenario(data,{pricePct:0,unitsPct:0,costPct:0,expensesPct:0,...change},ui.month);
   return tableRow([safe(title),r?money(r.net):'Không đủ dữ liệu',r?`<strong class="${r.net<base.net?'negative':'positive'}">${r.change>=0?'+':''}${money(r.change)}</strong>`:'—']);
 });
 return panel('Phân tích độ nhạy · phương án bất lợi',`${table(['Biến động giả định','Lợi nhuận sau biến động','Chênh lệch so với hiện tại'],rows)}<p class="caption">Thay đổi từng yếu tố riêng lẻ, các yếu tố khác giữ nguyên. Đây là mô phỏng điều kiện, không phải dự báo chắc chắn.</p>`);
}

function pageScenarios(){const sc=scenario(data,ui.scenario,ui.month),goal=goalSeek(data,ui.goal,ui.month),f=financials(data,ui.month);return `${head('Mô phỏng & mục tiêu lợi nhuận','Điều chỉnh giả định và so sánh kết quả; mô hình chỉ chạy khi biết đầy đủ giá vốn.')}${panel('Thay đổi các giả định',`<form id="scenario-form" class="scenario-grid"><label>Giá bán thay đổi (%)<input name="pricePct" type="number" step="1" min="-80" max="100" value="${ui.scenario.pricePct}" /></label><label>Số lượng bán thay đổi (%)<input name="unitsPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.unitsPct}" /></label><label>Giá vốn / đơn vị (%)<input name="costPct" type="number" step="1" min="-80" max="200" value="${ui.scenario.costPct}" /></label><label>Chi phí vận hành (%)<input name="expensesPct" type="number" step="1" min="-100" max="200" value="${ui.scenario.expensesPct}" /></label><button type="submit" class="btn primary">Tính lại phương án</button></form>`)}${sc?`<div class="metrics three">${card('Lợi nhuận cơ sở',money(sc.baseNet),'Từ giao dịch hoàn thành','◉')}${card('Lợi nhuận phương án',money(sc.net),'Theo giả định đã chọn','◇','purple')}${card('Chênh lệch',`${sc.change>=0?'+':''}${money(sc.change)}`,'Không phải dự báo doanh thu chắc chắn','↗',sc.change>=0?'green':'orange')}</div>`:`<div class="notice-warn">Không thể mô phỏng lợi nhuận vì còn ${f.missing.length} đơn thiếu giá vốn. Cần bổ sung dữ liệu hợp lệ, không tự đoán số liệu.</div>`}${sc?`<div class="decision-prompt"><strong>Đưa phương án vào quy trình phê duyệt</strong><p>Lưu giả định và kết quả mô phỏng để so sánh với thực tế sau khi thực hiện.</p>${btn('Lưu mô phỏng thành quyết định','scenario-to-decision','primary')}</div>`:''}${sensitivityPanel()}${panel('Tìm doanh thu mục tiêu (Goal-seeking)',`<form id="goal-form" class="row-control"><label>Mục tiêu lợi nhuận trước thuế (₫)<input type="text" data-money inputmode="numeric" pattern="[0-9.]*" autocomplete="off" name="goal" value="${formatVndInput(ui.goal)}"></label><button class="btn primary" type="submit">Tính doanh thu cần đạt</button></form>${goal?`<div class="result-box"><div><span>Doanh thu tối thiểu cần đạt</span><strong>${money(goal.requiredRevenue)}</strong></div><div><span>Doanh thu cần tăng thêm so với hiện tại</span><strong>${money(goal.moreRevenue)}</strong></div><p class="caption">Biên đóng góp: ${(goal.margin*100).toFixed(1)}%. ${goal.assumption}</p></div>`:`<p class="caption">Chưa đủ dữ liệu xác thực hoặc biên đóng góp không dương để giải bài toán.</p>`}`)}`;}
function podiumView(rank){if(!rank.length)return '';const order=[rank[1],rank[0],rank[2]].filter(Boolean);const place=x=>rank.indexOf(x)+1;return `<section class="podium-wrap" aria-label="Top nhà cung cấp"><div class="podium">${order.map(x=>`<div class="pod pod-${place(x)}"><span class="pod-medal">${['🥇','🥈','🥉'][place(x)-1]}</span><b>${safe(x.name)}</b><strong>${x.score.toFixed(2)}<small>/5</small></strong><i style="height:${place(x)===1?150:place(x)===2?112:88}px"><em>#${place(x)}</em></i></div>`).join('')}</div><p class="caption">Bục xếp hạng theo điểm tổng hợp có trọng số. Điểm giá/chất lượng là đánh giá của quản lý; điểm giao hàng tự tính khi có đủ phiếu.</p></section>`;}
function pageRanking(){let rank=[];try{rank=scoreSuppliers(data)}catch{}const productId=ui.compareProduct||data.products[0]?.id||'';let offers=[];try{if(productId)offers=compareSupplierOffers(data,productId,ui.compareQty)}catch{}const comparePanel=panel('So sánh giá thực tế trước khi đặt mua',`<form id="compare-supplier-form" class="row-control">${select('productId','Sản phẩm',pOpts(true),productId)}${input('quantity','Số lượng dự kiến',ui.compareQty,'number',true,'min="1" step="1"')}<button class="btn primary" type="submit">So sánh</button></form><p class="caption">Chỉ hiển thị đối tác có giá nhập từng được ghi nhận với sản phẩm này. Giá là tham khảo từ phiếu mua cũ, không phải báo giá hiện tại.</p>${table(['Nhà cung cấp','Giá mua gần nhất','Tiền hàng','Phí giao dự tính','Tổng dự tính','Đúng hẹn','Chọn đối tác'],offers.map(o=>tableRow([safe(o.supplier),`${money(o.unitPrice)}<small>${date(o.priceDate)}</small>`,money(o.merchandise),o.unknown?'Cần hỏi báo giá':money(o.freight),o.unknown?'Chưa xác định':`<strong>${money(o.estimatedTotal)}</strong>`,o.sample?`${o.onTimePct}% · ${o.sample} phiếu`:'Chưa đủ dữ liệu',btn('Tạo phiếu mua','buy-from-supplier','compact',`data-id="${safe(o.supplierId)}"`) ])))}${offers.length?'<p class="caption">Ước tính không gồm chi phí bốc xếp chưa biết. Hãy xác nhận phí và chất lượng trước khi chọn.</p>':''}`);return `${head('Đánh giá nhà cung cấp','So sánh chính sách và kết quả giao hàng có ghi nhận; phần chấm điểm 1–5 là đánh giá của người quản lý.')}${podiumView(rank)}${comparePanel}${panel('Trọng số đánh giá',`<form id="weights-form" class="row-control"><label>Giá (%)<input type="number" name="price" min="0" max="100" step="1" value="${data.weights.price}"></label><label>Giao hàng (%)<input type="number" name="delivery" min="0" max="100" step="1" value="${data.weights.delivery}"></label><label>Chất lượng (%)<input type="number" name="quality" min="0" max="100" step="1" value="${data.weights.quality}"></label><button type="submit" class="btn primary">Cập nhật trọng số</button></form><p class="caption">Trọng số được chuẩn hóa theo tổng, không bắt buộc tổng bằng 100. Chỉ nhà cung cấp đã được bạn chấm điểm mới xuất hiện trong xếp hạng. Điểm giao hàng tự tính khi có ít nhất 3 phiếu đã nhận ghi đủ ngày hẹn và ngày giao; nếu ít hơn, dùng điểm đánh giá do quản lý nhập. Giá và chất lượng vẫn cần đối chiếu báo giá, biên bản thực tế.</p>`)}${panel('Dữ liệu giao hàng thực tế',table(['Nhà cung cấp','Chính sách vận chuyển','Phiếu đã nhận có hẹn','Đúng hẹn','Giao đủ','Tổng giá trị đã nhập'],data.suppliers.filter(s=>s.type!=='Vận chuyển'&&s.type!=='Dịch vụ').map(s=>{const st=supplierDeliveryStats(data,s.id);const purchases=data.purchases.filter(p=>p.supplierId===s.id&&delivered(p));return tableRow([safe(s.name),safe(supplierPolicies(s)),`${st.sample} phiếu`,st.sample?`${st.onTimePct}%`:'Chưa đủ dữ liệu',st.sample?`${st.fillPct}% (lỗi ${st.defectPct}%)`:'Chưa đủ dữ liệu',money(purchases.reduce((z,p)=>z+Number(p.landedTotal||0),0))]);}))) }${panel('Ma trận đánh giá và xếp hạng',table(['Xếp hạng','Nhà cung cấp','Giá','Giao hàng','Chất lượng','Điểm tổng hợp','Thao tác'],rank.map((s,i)=>tableRow([`<strong>#${i+1}</strong>`,safe(s.name),integer(s.ratings.price)+'/5',`${integer(s.deliveryUsed)}/5${s.deliveryMeasured?' (tự tính)':''}`,integer(s.ratings.quality)+'/5',`<strong>${s.score.toFixed(2)}/5</strong>`,`${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(s.id)}"`)} ${btn('Nhập hàng','buy-from-supplier','compact',`data-id="${safe(s.id)}"`)}`]))))}${data.suppliers.some(x=>!data.ratings[x.id])?panel('Chưa chấm điểm',data.suppliers.filter(x=>!data.ratings[x.id]).map(x=>`<div class="unrated-row"><strong>${safe(x.name)}</strong>${btn('Chấm điểm','rate-supplier','compact',`data-id="${safe(x.id)}"`)}</div>`).join('')):''}${rank.length?`<div class="decision-prompt"><strong>Phương án dẫn đầu: ${safe(rank[0].name)}</strong><p>Điểm tổng hợp ${rank[0].score.toFixed(2)}/5 theo trọng số và điểm đã nhập. Điểm số là đánh giá chủ quan, cần kiểm chứng bằng dữ liệu thực.</p>${btn('Lưu đề xuất thành quyết định','rank-to-decision','primary')}</div>`:''}`;}
function pageAlerts(){const r=simpleRecommendation(data);const list=[...r.lateDeliveries.map(p=>({severity:'high',title:`Trễ hẹn giao hàng: ${supplierName(p.supplierId)}`,desc:`Phiếu ${p.id} dự kiến ${date(p.expectedDelivery)} nhưng chưa xác nhận đã nhận.`,act:'go-purchase'})),...r.low.map(p=>({severity:'high',title:`Tồn kho thấp: ${p.name}`,desc:`Còn ${p.stock}, ngưỡng ${p.min}; cần bổ sung tối thiểu ${Math.max(0,p.min-p.stock)} đơn vị tới ngưỡng.`,act:'suggest-replenishment',id:p.id})),...r.debts.map(p=>({severity:'medium',title:`Công nợ: ${p.name}`,desc:`Còn ${money(p.debt)} từ phiếu mua chưa thanh toán.`,act:'go-payment'})),...(r.unverified?[{severity:'high',title:'Thiếu dữ liệu giá vốn',desc:`Có ${r.unverified} đơn hoàn thành chưa đủ chi tiết để kết luận tổng lợi nhuận.`,act:'go-finance'}]:[])];return `${head('Cảnh báo kinh doanh','Cảnh báo từ các điều kiện có thể kiểm chứng; không giả định đây là thông báo AI.')}${panel('Danh sách cảnh báo theo mức độ',list.length?`<div class="alert-list">${list.map(x=>`<div class="alert-item ${x.severity}"><span>⚑</span><div><strong>${safe(x.title)}</strong><p>${safe(x.desc)}</p></div>${btn('Xử lý →',x.act,'compact',x.id?`data-id="${safe(x.id)}"`:'')}</div>`).join('')}</div>`:empty('Không có cảnh báo với dữ liệu và ngưỡng hiện tại.'))}`;}
function pageDecisions(){const cols=[['Đề xuất','Ý tưởng chờ xét duyệt','c5'],['Đã duyệt','Sẵn sàng thực hiện','c4'],['Đang thực hiện','Đang triển khai','c3'],['Hoàn thành','Đã có kết quả','c1'],['Hủy','Không tiếp tục','c6']];const next={'Đề xuất':'Đã duyệt','Đã duyệt':'Đang thực hiện','Đang thực hiện':'Hoàn thành'};
 const list=data.decisions.filter(d=>search(d.title+' '+d.reason));
 return `${head('Vòng đời quyết định','Ghi nhận vấn đề → phương án → phê duyệt → thực hiện → so sánh mục tiêu và kết quả.',btn('＋ Tạo quyết định','new-decision','primary'))}<div class="kanban" role="list">${cols.map(([st,hint,k])=>{const items=list.filter(d=>(d.status||'Đề xuất')===st);return `<section class="kcol" style="--k:var(--${k})" role="listitem" aria-label="${safe(st)}"><header><h2>${st}</h2><span class="kcount">${items.length}</span><small>${hint}</small></header><div class="kbody">${items.map(d=>`<article class="kcard"><b>${safe(d.title)}</b><p>${safe(String(d.reason||'').slice(0,130))}${String(d.reason||'').length>130?'…':''}</p><dl><div><dt>Phụ trách</dt><dd>${safe(d.owner||'—')}</dd></div><div><dt>Hạn</dt><dd>${date(d.due)}</dd></div></dl>${d.expected?`<small class="kexp">Kỳ vọng: ${safe(d.expected)}</small>`:''}${d.actual?`<small class="kexp act">Thực tế: ${safe(d.actual)}</small>`:''}<div class="kactions">${btn('Cập nhật','edit-decision','compact',`data-id="${safe(d.id)}"`)}${next[st]?btn('→ '+next[st],'decision-move','compact go',`data-id="${safe(d.id)}|${safe(next[st])}"`):''}</div></article>`).join('')||'<p class="kempty">Chưa có mục nào</p>'}</div></section>`}).join('')}</div>`;}

function pageSettings(){return `${head('Hồ sơ và cấu hình doanh nghiệp','Đổi tên doanh nghiệp sẽ cập nhật tên trên menu và báo cáo, đồng thời được lưu vào dữ liệu.')}${panel('Thông tin doanh nghiệp',`<form id="settings-form" class="form-grid"><label>Tên doanh nghiệp / cửa hàng<input name="name" required maxlength="120" value="${safe(data.company.name)}"></label><label>Ngành nghề<input name="sector" maxlength="100" value="${safe(data.company.sector||'')}"></label><label>Số điện thoại<input name="phone" maxlength="40" value="${safe(data.company.phone||'')}"></label><label>Email<input name="email" type="email" maxlength="120" value="${safe(data.company.email||'')}"></label><label class="wide">Địa chỉ<input name="address" maxlength="240" value="${safe(data.company.address||'')}"></label><div class="wide"><button type="submit" class="btn primary">Lưu thông tin doanh nghiệp</button></div></form>`)}${panel('Giao diện cá nhân hóa',`<div class="config-grid"><div><h3>Màu chủ đạo</h3><div class="theme-grid">${themeMeta.map(([id,label,a1,a2,a3])=>`<button type="button" class="theme-card ${prefs.theme===id?'current':''}" data-preference="theme" data-value="${id}" aria-pressed="${prefs.theme===id}" aria-label="Bảng màu ${label}"><span class="swatch" style="background:linear-gradient(135deg,${a1} 0 38%,${a2} 38% 70%,${a3} 70%)"></span><b>${label}</b></button>`).join('')}</div></div><div class="mode-row"><span class="mode-label">Chế độ sáng / tối</span>${modeSwitch()}</div><div class="mode-row"><span class="mode-label">Cỡ chữ</span>${fontSwitch()}</div><label>Ngôn ngữ / Language<select data-preference="lang"><option value="vi" ${prefs.lang==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${prefs.lang==='en'?'selected':''}>English</option></select></label><label class="wide">Logo doanh nghiệp (ảnh JPG/PNG/WebP)<input type="file" id="company-logo-file" accept="image/jpeg,image/png,image/webp"></label>${data.company.logo?`<div class="wide settings-actions"><button type="button" class="btn danger" data-action="remove-company-logo">Xóa logo đã tải</button></div>`:""}<p class="caption wide">Tùy chỉnh giao diện được ghi nhớ trên thiết bị; logo doanh nghiệp được đồng bộ với dữ liệu doanh nghiệp.</p></div>`)}${panel('Thành viên & bảo mật',`<p class="muted">Tài khoản đang dùng: <strong>${safe(cloud.user?.email||'Chế độ xem thử')}</strong> · Vai trò: <strong>${safe(cloud.org?.role||'Xem thử')}</strong></p><div class="settings-actions">${btn('Tạo mã mời 7 ngày','create-invite','primary')}${btn('Chuyển doanh nghiệp','switch-org')}${btn('Đổi mật khẩu','change-password')}${btn('Đăng xuất','logout')}</div><div id="invite-output" class="caption"></div>`)}${panel('Dữ liệu & sao lưu',`<p class="muted">Bản v7 lưu dữ liệu làm việc của mỗi doanh nghiệp trên Supabase sau khi đăng nhập, với quyền thành viên tách biệt. Chứng từ tải lên lưu trong vùng Storage riêng. Chế độ xem thử vẫn sử dụng trình duyệt và không chia sẻ. Hãy xuất bản sao lưu trước khi xóa dữ liệu trình duyệt. Trong chế độ đăng nhập, chứng từ mới được lưu ở Storage riêng của doanh nghiệp; bản demo có thể dùng lưu trữ cục bộ. Không tải lên chứng từ nếu chưa xác nhận người nhận đúng.</p><div class="settings-actions">${btn('↓ Xuất bản sao lưu JSON','backup','primary')}${btn('↑ Nhập sao lưu v3 / bản cũ','restore')}${btn('↗ Chuyển dữ liệu từ phiên bản cũ','migrate')}${btn('Khởi tạo dữ liệu mẫu','reset-demo')}${btn('Bắt đầu dữ liệu trống','reset-empty','danger')}</div><input type="file" id="restore-file" accept="application/json,.json" hidden><p class="caption">Dữ liệu demo cũ được giữ riêng và không tự chuyển vào doanh nghiệp mới. Có thể khôi phục từ bản sao lưu trong cùng trình duyệt / tên miền, hoặc tải lên tệp sao lưu smartdecision-local-v1 cũ. Các giao dịch lịch sử thiếu giá vốn sẽ tiếp tục được ghi nhãn chưa xác minh.</p>`)}}`;}
const moduleIdentity={
 orders:{icon:'🛍',tone:'rose',tag:'BÁN HÀNG',hint:'Từ đơn hàng đến thanh toán',links:[['customers','Khách hàng','♙'],['finance','Dòng tiền','↗'],['products','Sản phẩm','◈']]},
 products:{icon:'◈',tone:'amber',tag:'DANH MỤC',hint:'Sản phẩm · giá bán · giá vốn',links:[['inventory','Xem tồn kho','▣'],['suppliers','Đặt mua hàng','♧'],['forecast','Nhu cầu','⌁']]},
 inventory:{icon:'▣',tone:'cyan',tag:'KHO VẬN',hint:'Tồn thực · biến động · kiểm kê',links:[['suppliers','Nhập hàng','♧'],['forecast','Dự báo','⌁'],['orders','Xuất bán','▤']]},
 suppliers:{icon:'♧',tone:'teal',tag:'MUA HÀNG',hint:'Đối tác · nhận hàng · công nợ',links:[['inventory','Kho hàng','▣'],['ranking','So sánh NCC','⚖'],['finance','Tài chính','◉']]},
 customers:{icon:'♙',tone:'indigo',tag:'KHÁCH HÀNG',hint:'Hồ sơ · lịch sử · phải thu',links:[['orders','Đơn hàng','▤'],['finance','Khoản phải thu','◉'],['analytics','Phân tích','▥']]},
 finance:{icon:'◉',tone:'mint',tag:'TÀI CHÍNH',hint:'Doanh thu · lợi nhuận · dòng tiền',links:[['orders','Thu từ khách','▤'],['suppliers','Trả nhà cung cấp','♧'],['scenarios','Mô phỏng','◇']]},
 analytics:{icon:'▥',tone:'purple',tag:'PHÂN TÍCH',hint:'Xu hướng · sản phẩm · hiệu quả',links:[['finance','Báo cáo tài chính','◉'],['forecast','Dự báo nhu cầu','⌁'],['decisions','Quyết định','◎']]},
 forecast:{icon:'⌁',tone:'cyan',tag:'DỰ BÁO',hint:'Dữ liệu → mô hình → quyết định',links:[['inventory','Kiểm tra tồn','▣'],['suppliers','Đặt hàng','♧'],['decisions','Lưu phương án','◎']]},
 scenarios:{icon:'◇',tone:'amber',tag:'MÔ PHỎNG',hint:'Thử kịch bản trước khi áp dụng',links:[['finance','Số liệu cơ sở','◉'],['analytics','Phân tích','▥'],['decisions','Theo dõi','◎']]},
 ranking:{icon:'⚖',tone:'rose',tag:'ĐÁNH GIÁ ĐỐI TÁC',hint:'So sánh tổng chi phí và giao hàng',links:[['suppliers','Hồ sơ & phiếu mua','♧'],['forecast','Nhu cầu nhập','⌁'],['decisions','Quyết định','◎']]},
 decisions:{icon:'◎',tone:'indigo',tag:'QUẢN TRỊ QUYẾT ĐỊNH',hint:'Đề xuất → xét duyệt → kết quả',links:[['forecast','Dự báo','⌁'],['scenarios','Mô phỏng','◇'],['ranking','Đánh giá NCC','⚖']]},
 settings:{icon:'⚙',tone:'blue',tag:'THIẾT LẬP',hint:'Thông tin · logo · giao diện · dữ liệu',links:[['dashboard','Trung tâm điều hành','▦'],['products','Sản phẩm','◈'],['finance','Tài chính','◉']]}
};
function moduleHub(){const x=moduleIdentity[ui.page];if(!x)return '';return `<section class="module-hub tone-${x.tone}" aria-label="Điều hướng nghiệp vụ"><div class="module-emblem" aria-hidden="true">${x.icon}</div><div class="module-lead"><span>${x.tag}</span><h2>${safe(titles[ui.page])}</h2><p>${x.hint}</p></div><div class="module-crosslinks">${x.links.map(([id,label,icon])=>`<button type="button" data-go="${id}"><span>${icon}</span><b>${safe(label)}</b><i>↗</i></button>`).join('')}</div></section>`;}
