function countUpNumbers(root){try{if(globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches||typeof requestAnimationFrame!=='function')return;
 root.querySelectorAll('.db-kpi strong,.rm-page .metric strong,.db-ring b').forEach(el=>{if(el.children.length)return;const text=el.textContent||'';const m=text.match(/^(\D*?)(-?)(\d[\d.]*)(.*)$/);if(!m)return;const digits=m[3].replace(/\./g,'');if(!/^\d+$/.test(digits)||digits.length>13)return;const target=Number(digits);if(target<10)return;const grouped=m[3].includes('.');const t0=performance.now(),dur=750;
  const fmt=v=>{const n=Math.round(v);return grouped?String(n).replace(/\B(?=(\d{3})+(?!\d))/g,'.'):String(n);};
  const tick=now=>{if(!el.isConnected)return;const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);el.textContent=m[1]+m[2]+fmt(target*e)+m[4];if(k<1)requestAnimationFrame(tick);else el.textContent=text;};requestAnimationFrame(tick);});}catch{}}
