const alertCount=()=>{const r=simpleRecommendation(data);return r.low.length+r.lateDeliveries.length+r.debts.length+(r.unverified?1:0);};
function humanizeAi(text){
 let v=String(text||'').replace(/\\text\{([^{}]*)\}/g,'$1').replace(/\\times/g,' × ').replace(/\\cdot/g,' · ')
  .replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g,'($1 / $2)')
  .replace(/\\\[|\\\]|\\\(|\\\)/g,'').replace(/\$\$/g,'').replace(/\\%/g,'%');
 return v.replace(/\\left|\\right/g,'').replace(/\\approx/g,'≈').replace(/\\leq/g,'≤').replace(/\\geq/g,'≥');
}
function renderAiMessage(text){
 const v=humanizeAi(text);
 return v.split(/\r?\n/).map(line=>{
  let t=safe(line).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');
  const h=t.match(/^\s*#{1,4}\s+(.+)$/);if(h)return `<div class="ai-heading">${h[1]}</div>`;
  if(/^\s*(?:[-*•]|\d+[.)])\s+/.test(t))return `<div class="ai-item">${t.replace(/^\s*(?:[-*•]|\d+[.)])\s+/,'')} </div>`;
  return t?`<div class="ai-line">${t}</div>`:'<div class="ai-spacer"></div>';
 }).join('');
}
function chatHtml(){if(!ui.chatOpen)return '';const pos=ui.chatPos?`left:${Math.max(0,Math.min(innerWidth-310,ui.chatPos.x))}px;top:${Math.max(0,Math.min(innerHeight-240,ui.chatPos.y))}px;right:auto;bottom:auto;`:'';return `<div class="chat-panel" style="${pos}"><div class="chat-head" id="chat-handle"><span class="chat-logo">✦</span><div><strong>Trợ lý RetailMind</strong><small>⠿ Giữ và kéo thanh này để di chuyển</small></div><button type="button" data-action="reset-chat-position" class="icon-button" aria-label="Đặt lại vị trí" title="Đặt lại vị trí">⤢</button><button type="button" data-action="toggle-chat" class="icon-button" aria-label="Đóng">✕</button></div><div class="chat-body" id="chat-body">${ui.chat.map(x=>`<div class="bubble ${x.role==='user'?'user':'assistant'}">${x.role==='user'?safe(x.text):renderAiMessage(x.text)}</div>`).join('')}${ui.chatBusy?'<div class="bubble assistant">Đang phân tích yêu cầu…</div>':''}</div><div class="chat-actionbar"><button type="button" class="chat-voice-mode chat-talk ${ui.talkActive?'on':''}" data-action="talk-mode" aria-pressed="${ui.talkActive?'true':'false'}"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg><span>${ui.talkActive?({listening:'Đang nghe… (bấm để dừng)',thinking:'Đang suy nghĩ… (bấm để dừng)',speaking:'Đang trả lời… (bấm để dừng)'}[ui.talkState]||'Đang trò chuyện (bấm để dừng)'):'Trò chuyện'}</span></button><button type="button" data-action="chat-to-decision" class="chat-save-decision" title="Chỉ lưu đề xuất sau khi bạn xác nhận">＋ Lưu phân tích thành đề xuất</button></div><div class="prompt-chips"><button data-chat-prompt="Phân tích doanh thu và giới hạn của dữ liệu">Doanh thu</button><button data-chat-prompt="Các sản phẩm cần nhập kho ưu tiên">Cảnh báo kho</button><button data-chat-prompt="Gợi ý phương án cải thiện lợi nhuận">Quyết định</button></div><form id="chat-form" class="chat-form"><input name="question" placeholder="Hỏi về hoạt động kinh doanh..." value="${safe(ui.chatInput)}" ${ui.chatBusy?'disabled':''} required><button type="button" class="chat-mic" data-action="mic" aria-label="Nhập bằng giọng nói" title="Nói bằng giọng nói"><svg viewBox="0 0 24 24" aria-hidden="true" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/></svg></button><button type="submit" ${ui.chatBusy?'disabled':''} aria-label="Gửi">➜</button></form></div>`;}
